{
  "packet_id": "H6-T04-1",
  "claim_id": "C021",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C021.component",
    "value": "Where feasible, eligible accounts should be randomly assigned between the selected change and the existing experience with identical measurement.",
    "scope": "A conditional comparison design, not an assertion that randomization is feasible or has occurred; eligibility is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the feasibility condition, eligible population, comparison and identical measurement requirement."
    }
  },
  "signal_basis": {
    "component_id": "C021.signal_basis",
    "value": "Compare first-publication rates within a common window, time to publication, targeted-checkpoint retention and predefined guardrails between eligible accounts randomly assigned to the change or existing experience, using identical measurement.",
    "scope": "The proposed release comparison where random assignment is feasible; no favorable result is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the comparison design, measurement constraint and observed outcomes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required to warrant this conditional comparison design."
    }
  },
  "rationale": "Random assignment provides a justified method for reducing confounding in the release comparison, while identical measurement supports comparable outcome assessment. This licenses the bounded design recommendation without establishing feasibility, benefit or a mechanism.",
  "uncertainty": "Eligibility is unspecified, leaving the comparison population undefined; this does not invalidate the conditional recommendation.",
  "anomalies": []
}
